  "after-wave.body": {
    tr: "Bu kısa yazı, zor bir an geçtikten sonra içindir. Bir kalem ve kâğıt al.\n\nÜç başlık yaz ve her birinin altına bir iki cümle ekle.\n\nBir: Beden. Şu an bedeninin neresi biraz daha rahat? Küçük bir fark bile olur.\n\nİki: Oda. Etrafında gördüğün bir eşyanın adını yaz.\n\nÜç: Teşekkür. Bugün sana iyi gelen küçük ve gerçek bir şey.\n\nYorum yapmana, analiz etmene gerek yok. Bitirince defteri kapat. Bu bir rapor değil, sadece kısa bir mola.",
    en: "This short writing exercise is for after a difficult moment has passed. Take a pen and some paper.\n\nWrite three headings, and add a sentence or two under each.\n\nOne: Body. Which part of your body feels a little easier right now? Even a small difference counts.\n\nTwo: Room. Write the name of one object you can see around you.\n\nThree: Thanks. One small, real thing that did you good today.\n\nThere is no need to comment or analyze. When you are done, close the notebook. This is not a report, just a short pause.",
    az: "Bu qısa yazı çətin bir an keçdikdən sonra üçündür. Qələm və kağız götür.\n\nÜç başlıq yaz və hər birinin altına bir-iki cümlə əlavə et.\n\nBir: Bədən. İndi bədəninin harası bir az daha rahatdır? Kiçik bir fərq də olar.\n\nİki: Otaq. Ətrafında gördüyün bir əşyanın adını yaz.\n\nÜç: Təşəkkür. Bu gün sənə xoş gələn kiçik və həqiqi bir şey.\n\nŞərh yazmağa, təhlil etməyə ehtiyac yoxdur. Bitirəndə dəftəri bağla. Bu hesabat deyil, sadəcə qısa bir fasilədir.",
    ru: "Это короткое упражнение для момента, когда трудная минута уже позади. Возьми ручку и лист бумаги.\n\nНапиши три заголовка и под каждым — одно-два предложения.\n\nПервое: тело. Где в теле сейчас стало чуть легче? Даже маленькая разница считается.\n\nВторое: комната. Напиши название одного предмета, который видишь рядом.\n\nТретье: спасибо. Одна маленькая настоящая вещь, которая сегодня была тебе в радость.\n\nКомментировать и анализировать не нужно. Когда закончишь, закрой тетрадь. Это не отчёт, а просто короткая передышка.",
    es: "Este breve ejercicio de escritura es para cuando un momento difícil ya ha pasado. Toma un bolígrafo y un papel.\n\nEscribe tres títulos y añade una o dos frases debajo de cada uno.\n\nUno: cuerpo. ¿Qué parte de tu cuerpo está un poco más tranquila ahora? Incluso una diferencia pequeña cuenta.\n\nDos: habitación. Escribe el nombre de un objeto que veas a tu alrededor.\n\nTres: gracias. Algo pequeño y real que hoy te ha sentado bien.\n\nNo hace falta comentar ni analizar. Cuando termines, cierra el cuaderno. No es un informe, solo una pausa breve.",
    it: "Questo breve esercizio di scrittura è per quando un momento difficile è passato. Prendi una penna e un foglio.\n\nScrivi tre titoli e aggiungi una o due frasi sotto ciascuno.\n\nUno: il corpo. Quale parte del corpo è un po’ più tranquilla adesso? Anche una piccola differenza conta.\n\nDue: la stanza. Scrivi il nome di un oggetto che vedi intorno a te.\n\nTre: grazie. Una cosa piccola e vera che oggi ti ha fatto bene.\n\nNon serve commentare o analizzare. Quando hai finito, chiudi il quaderno. Non è un resoconto, solo una breve pausa.",
  },
