  "lab-3.title": {
    tr: "3. gece: Zihindeki mahkeme",
    en: "Night 3: The courtroom in your mind",
    az: "3-cü gecə: Ağıldakı məhkəmə",
    ru: "Ночь 3. Суд в голове",
    es: "Noche 3: El juicio de la mente",
    it: "Notte 3: Il tribunale della mente",
  },
  "lab-4.body": {
    tr: "Bu gece yatmadan önce kısa, sakin bir ritüel kur ve her gece aynı sırayla tekrarla.\n\nÖrneğin: Işıkları kıs. Ekranları kapat. Ilık bir su ya da bitki çayı iç, ya da birkaç dakika yavaşça esne. Sonra yatağa geç.\n\nBu sihir değil, bir işaret. Beden aynı sırayı her gece gördükçe uykunun yaklaştığını öğrenir.\n\nRitüeli mükemmel yapmaya çalışma. Basit ve hep aynı olması yeterli.",
    en: "Tonight, create a short, calm ritual before bed, and repeat it in the same order every night.\n\nFor example: dim the lights. Switch off the screens. Drink some warm water or herbal tea, or stretch slowly for a few minutes. Then get into bed.\n\nThis is not magic; it is a signal. When the body sees the same order every night, it learns that sleep is near.\n\nDo not try to make the ritual perfect. It only needs to be simple and the same.",
    az: "Bu gecə yatmazdan əvvəl qısa, sakit bir ritual qur və hər gecə eyni ardıcıllıqla təkrarla.\n\nMəsələn: İşıqları azalt. Ekranları söndür. İlıq su və ya bitki çayı iç, ya da bir neçə dəqiqə yavaşca dartın. Sonra yatağa keç.\n\nBu sehr deyil, bir işarədir. Bədən hər gecə eyni ardıcıllığı görəndə yuxunun yaxınlaşdığını öyrənir.\n\nRitualı mükəmməl etməyə çalışma. Sadə və həmişə eyni olması kifayətdir.",
    ru: "Этим вечером создай короткий спокойный ритуал перед сном и повторяй его каждый вечер в одном и том же порядке.\n\nНапример: приглуши свет. Выключи экраны. Выпей тёплой воды или травяного чая, или несколько минут медленно потянись. Потом ложись в постель.\n\nЭто не волшебство, а сигнал. Когда тело каждый вечер видит один и тот же порядок, оно понимает, что скоро сон.\n\nНе старайся сделать ритуал идеальным. Достаточно, чтобы он был простым и всегда одинаковым.",
    es: "Esta noche, crea un ritual breve y tranquilo antes de dormir, y repítelo cada noche en el mismo orden.\n\nPor ejemplo: baja las luces. Apaga las pantallas. Bebe agua tibia o una infusión, o estírate despacio unos minutos. Después métete en la cama.\n\nNo es magia, es una señal. Cuando el cuerpo ve el mismo orden cada noche, aprende que el sueño está cerca.\n\nNo intentes que el ritual sea perfecto. Basta con que sea sencillo y siempre igual.",
    it: "Stasera crea un breve rituale tranquillo prima di dormire e ripetilo ogni sera nello stesso ordine.\n\nPer esempio: abbassa le luci. Spegni gli schermi. Bevi un po’ d’acqua tiepida o una tisana, oppure fai qualche minuto di stretching lento. Poi vai a letto.\n\nNon è magia, è un segnale. Quando il corpo vede lo stesso ordine ogni sera, impara che il sonno è vicino.\n\nNon cercare di rendere il rituale perfetto. Basta che sia semplice e sempre uguale.",
  },
  "lab-4.nightSeed": {
    tr: "Ilık su, kısık ışık, yumuşak battaniye.",
    en: "Warm water, low light, a soft blanket.",
    az: "İlıq su, zəif işıq, yumşaq yorğan.",
    ru: "Тёплая вода, приглушённый свет, мягкое одеяло.",
    es: "Agua tibia, luz baja, una manta suave.",
    it: "Acqua tiepida, luce bassa, una coperta morbida.",
  },
  "lab-4.sentence": {
    tr: "Sıra hep aynı, bedenim öğreniyor.",
    en: "The order is always the same, and my body is learning.",
    az: "Ardıcıllıq həmişə eynidir, bədənim öyrənir.",
    ru: "Порядок всегда один и тот же, и тело учится.",
    es: "El orden es siempre el mismo y mi cuerpo aprende.",
    it: "L’ordine è sempre lo stesso e il mio corpo impara.",
  },
  "lab-4.subtitle": {
    tr: "Her gece aynı sıra",
    en: "The same order every night",
    az: "Hər gecə eyni ardıcıllıq",
    ru: "Каждый вечер в одном порядке",
    es: "El mismo orden cada noche",
    it: "Lo stesso ordine ogni sera",
  },
  "lab-4.title": {
    tr: "4. gece: Yavaşlama ritüeli",
    en: "Night 4: A wind-down ritual",
    az: "4-cü gecə: Sakitləşmə ritualı",
    ru: "Ночь 4. Ритуал замедления",
    es: "Noche 4: Un ritual para bajar el ritmo",
    it: "Notte 4: Un rituale per rallentare",
  },
  "lab-5.body": {
    tr: "Bu gece uykuya tek bir sakin görüntüyle geç. Bir kartpostal gibi: kapalı bir bahçe, güneşte ısınmış bir taş, yanan bir lamba.\n\nÖnce bedenini yumuşat. Omuzlarını bırak, çeneni gevşet, nefesini yavaşlat.\n\nSonra görüntüyü bir kez hatırla. Onu sürekli tekrarlamana ya da büyütmene gerek yok.\n\nUyku bir görev değil. Sen sadece kapıyı aralık bırakıyorsun; gerisi kendiliğinden gelir.",
    en: "Tonight, drift into sleep with one calm image. Like a postcard: a walled garden, a stone warm from the sun, a glowing lamp.\n\nFirst, soften your body. Let your shoulders drop, loosen your jaw, and slow your breathing.\n\nThen recall the image once. You do not need to keep repeating it or make it bigger.\n\nSleep is not a task. You are simply leaving the door ajar; the rest comes by itself.",
    az: "Bu gecə yuxuya tək bir sakit görüntü ilə get. Açıqca kimi: bağlı bir bağ, günəşdə qızmış bir daş, yanan bir lampa.\n\nƏvvəlcə bədənini yumşalt. Çiyinlərini burax, çənəni boşalt, nəfəsini yavaşlat.\n\nSonra görüntünü bir dəfə xatırla. Onu durmadan təkrarlamağa və ya böyütməyə ehtiyac yoxdur.\n\nYuxu tapşırıq deyil. Sən sadəcə qapını aralı qoyursan; qalanı öz-özünə gəlir.",
    ru: "Этой ночью засыпай с одним спокойным образом. Как открытка: закрытый сад, нагретый солнцем камень, горящая лампа.\n\nСначала расслабь тело. Опусти плечи, разожми челюсть, замедли дыхание.\n\nПотом один раз вспомни образ. Не нужно постоянно повторять его или делать больше.\n\nСон — это не задача. Ты просто оставляешь дверь приоткрытой; остальное придёт само.",
    es: "Esta noche, duérmete con una sola imagen tranquila. Como una postal: un jardín cerrado, una piedra calentada por el sol, una lámpara encendida.\n\nPrimero, suaviza el cuerpo. Deja caer los hombros, afloja la mandíbula y respira más despacio.\n\nLuego recuerda la imagen una vez. No hace falta repetirla sin parar ni hacerla más grande.\n\nDormir no es una tarea. Solo dejas la puerta entreabierta; lo demás llega solo.",
    it: "Stanotte addormentati con una sola immagine tranquilla. Come una cartolina: un giardino chiuso, una pietra scaldata dal sole, una lampada accesa.\n\nPrima ammorbidisci il corpo. Lascia scendere le spalle, rilassa la mascella e rallenta il respiro.\n\nPoi richiama l’immagine una volta. Non serve ripeterla di continuo o renderla più grande.\n\nDormire non è un compito. Lasci solo la porta socchiusa; il resto arriva da sé.",
  },
