  "panic-3-b0.title": {
    tr: "Kaburgalar yanlara",
    en: "Ribs to the sides",
    az: "Qabırğalar yanlara",
    ru: "Рёбра в стороны",
    es: "Costillas hacia los lados",
    it: "Costole ai lati",
  },
  "panic-3-b1.body": {
    tr: "Dörde kadar sayarak nefes al, ikiye kadar tut, altıya kadar sayarak ver. Verirken ağzın hafif açık olabilir. Başın dönerse normal nefese dön; zorlama. Bu bir performans değil.",
    en: "Breathe in for a count of four, hold for two, and breathe out for six. Your mouth can be slightly open as you breathe out. If you feel dizzy, return to normal breathing; do not force it. This is not a performance.",
    az: "Dördə qədər sayaraq nəfəs al, ikiyə qədər saxla, altıya qədər sayaraq ver. Nəfəs verəndə ağzın bir az açıq ola bilər. Başın gicəllənsə, adi nəfəsə qayıt; zorlama. Bu tamaşa deyil.",
    ru: "Вдыхай на счёт четыре, задержи на два, выдыхай на счёт шесть. На выдохе рот может быть чуть приоткрыт. Если кружится голова, вернись к обычному дыханию; не заставляй себя. Это не выступление.",
    es: "Inspira contando hasta cuatro, retén hasta dos y espira contando hasta seis. Al espirar, la boca puede estar un poco abierta. Si te mareas, vuelve a la respiración normal; no fuerces. Esto no es una actuación.",
    it: "Inspira contando fino a quattro, trattieni fino a due ed espira contando fino a sei. Mentre espiri, la bocca può restare un po’ aperta. Se ti gira la testa, torna al respiro normale; non forzare. Non è una prestazione.",
  },
